import re
import random
import chess
import sys

def run_solution(fen):
    for pattern, repl in json.load(open("/app/re.json")):
        fen = re.sub(pattern, repl, fen)
    return fen.split("\n")

def our_moves(fen):
    fens = [" ".join(x.split(" ")[:-2]) for x in run_solution(fen)]
    # de-dup preserving order
    seen = set()
    out = []
    for x in fens:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def py_moves(fen):
    board = chess.Board(fen)
    res = set()
    for move in board.legal_moves:
        if move.promotion and move.promotion != chess.QUEEN:
            continue
        b = board.copy()
        b.push(move)
        res.add(" ".join(b.fen().split(" ")[:-2]))
    return res

def compare(fen, verbose=False):
    ours = our_moves(fen)
    theirs = py_moves(fen)
    ok = True
    extra = [x for x in ours if x not in theirs]
    missing = [x for x in theirs if x not in ours]
    if extra or missing:
        ok = False
    if verbose or not ok:
        print("FEN:", fen)
        print("  ours:", len(ours), "theirs:", len(theirs))
        if extra:
            print("  EXTRA:", extra)
        if missing:
            print("  MISSING:", missing)
    return ok, ours, theirs

def random_position():
    # Generate random positions with weighted materials but always white to move
    # Use various methods to get interesting positions
    r = random.random()
    board = chess.Board()
    if r < 0.5:
        # random game
        for _ in range(random.randint(10, 60)):
            try:
                lm = list(board.legal_moves)
                if not lm:
                    break
                board.push(random.choice(lm))
            except Exception:
                break
        return board.fen()
    else:
        # random piece placement: build a position manually
        for _ in range(50):
            try:
                lm = list(board.legal_moves)
                if not lm:
                    break
                board.push(random.choice(lm))
            except Exception:
                break
        return board.fen()

def main():
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 200
    seed = int(sys.argv[2]) if len(sys.argv) > 2 else 1
    random.seed(seed)
    fails = 0
    for i in range(n):
        # alternate position generators
        fen = random_position()
        try:
            ok, ours, theirs = compare(fen, verbose=(fails < 10))
            if not ok:
                fails += 1
                print("FAIL #", fails)
                sys.stdout.flush()
        except Exception as e:
            print("EXC on", fen, e)
            fails += 1
        if fails > 30:
            print("Too many failures, stopping.")
            break
    print("Done. fails =", fails)

if __name__ == "__main__":
    main()
